from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    separate_groups = []  # Initialize an empty list to store the separate groups
    current_group = ""  # Initialize an empty string to track the current group

    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            separate_groups.append(current_group)  # Append each separate group to the list
            current_group = ""  # Reset the current group

    return separate_groups  # Return the list of separate groups
